test_trajectory <- function(ctx) {
  f <- make_trajectory_fixture(seed = 404, n_features = 260, n_per_stage = 6)
  record_test("trajectory_shared_pca_safeguard", { z <- run_pca_core(t(preprocess_expr(f$quantity, TRUE, 0.5))); expect_true(!"P001" %in% colnames(z$sample_matrix), "Constant feature was retained by PCA") })
  record_test("trajectory_slingshot", { if (!require_namespace_or_skip("slingshot", "Slingshot regression")) return(invisible(NULL)); if (!require_namespace_or_skip("SingleCellExperiment", "Slingshot regression")) return(invisible(NULL)); d <- file.path(ctx$outputs, "trajectory"); dir.create(d, recursive = TRUE); run_slingshot_pseudotime(f$quantity, f$group_info, d, reduction = "PCA", start_group = "Stage1", end_group = "Stage4", top_n = 5, width = 3, height = 3); expect_file_nonempty(file.path(d, "slingshot_pseudotime_trajectory.pdf")); expect_file_nonempty(file.path(d, "slingshot_sample_pseudotime.csv")); expect_false(file.exists(file.path(d, "Slingshot_PCA_curve.pdf")), "Duplicate Slingshot trajectory output was generated"); expect_no_duplicates(list.files(d, pattern = "[.]pdf$")) }, required = FALSE)
  record_test("slingshot_plot_output_mapping", { if (!requireNamespace("slingshot", quietly = TRUE) || !requireNamespace("SingleCellExperiment", quietly = TRUE)) return(invisible(NULL)); d <- file.path(ctx$outputs, "trajectory"); pdfs <- list.files(d, pattern = "[.]pdf$", full.names = FALSE); expect_true("slingshot_pseudotime_trajectory.pdf" %in% pdfs, "Canonical trajectory output key missing"); expect_true(length(pdfs) == length(unique(pdfs)), "Trajectory PDF filenames are not unique") }, required = FALSE)
}
